sealed class Result {
    data class Success(val value: Int) : Result()
    data class Error(val message: String) : Result()
}

// Inside the library: compiler forces handling of any new subtype.
fun render(r: Result): String = when (r) {
    is Result.Success -> "ok ${r.value}"
    is Result.Error   -> "err ${r.message}"
}

// In a consumer's code:
fun log(r: Result) = when (r) {
    is Result.Success -> "ok"
    else              -> "unexpected"   // <-- a third subtype lands HERE silently
}

