enum class Status { PENDING, ACTIVE, BLOCKED }

// values() clones every call; entries is cached and immutable
fun count(list: List<Status>): Int {
    var n = 0
    for (s in list) for (c in Status.entries) if (c == s) n++  // fine
    return n
}

